    @Test
    void corporateDiscountDependsOnTheCompany() {
        Price tecnosul = calculator.calculate(deluxe,
                stay(LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "TECNOSUL"));
        assertEquals(new BigDecimal("779.80"), tecnosul.subtotal());
        assertEquals(new BigDecimal("93.58"), tecnosul.discount());
        assertEquals(new BigDecimal("686.22"), tecnosul.total());

        Price agrovale = calculator.calculate(deluxe,
                stay(LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "AGROVALE"));
        assertEquals(new BigDecimal("140.36"), agrovale.discount());
        Price farmavida = calculator.calculate(deluxe,
                stay(LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.CORPORATE, "FARMAVIDA"));
