        assertEquals(ErrorCode.INVALID_REQUEST,
                errorOf(() -> calculator.calculate(deluxe, stay(in, out, RatePlan.CORPORATE, "OUTRA"))));
    }

    @Test
    void otherPlansIgnoreTheCompanyCode() {
        Price price = calculator.calculate(deluxe,
                stay(LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), RatePlan.STANDARD, "TECNOSUL"));
        assertEquals(new BigDecimal("0.00"), price.discount());
    }

    @Test
    void weekendPackageIsAClosedPriceAllYear() {
        Price march = calculator.calculate(deluxe, stay(LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 14),
                RatePlan.WEEKEND_PACKAGE));
        assertEquals(2, march.nights());
        assertEquals(new BigDecimal("820.00"), march.subtotal());
        assertEquals(new BigDecimal("0.00"), march.discount());
        assertEquals(new BigDecimal("820.00"), march.total());

        Price highSeason = calculator.calculate(standardRoom, stay(LocalDate.of(2027, 7, 9),
                LocalDate.of(2027, 7, 11), RatePlan.WEEKEND_PACKAGE));
        assertEquals(new BigDecimal("520.00"), highSeason.total());
        Price suitePrice = calculator.calculate(suite, stay(LocalDate.of(2027, 7, 9),
                LocalDate.of(2027, 7, 11), RatePlan.WEEKEND_PACKAGE));
        assertEquals(new BigDecimal("1200.00"), suitePrice.total());
    }

    @Test
    void weekendPackageOnlyFromFridayToSunday() {
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(deluxe,
                stay(LocalDate.of(2027, 3, 11), LocalDate.of(2027, 3, 13), RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(deluxe,
                stay(LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 15), RatePlan.WEEKEND_PACKAGE))));
        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(deluxe,
                stay(LocalDate.of(2027, 3, 12), LocalDate.of(2027, 3, 13), RatePlan.WEEKEND_PACKAGE))));
    }

    @Test
    void longStayTakes10PercentOffFromSevenNights() {
        Price price = calculator.calculate(standardRoom,
                stay(LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 8), RatePlan.LONG_STAY));
        assertEquals(new BigDecimal("1749.30"), price.subtotal());
        assertEquals(new BigDecimal("174.93"), price.discount());
        assertEquals(new BigDecimal("1574.37"), price.total());

        assertEquals(ErrorCode.INVALID_REQUEST, errorOf(() -> calculator.calculate(standardRoom,
                stay(LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 7), RatePlan.LONG_STAY))));
    }

    @Test
    void longStayKeepsTheHighSeasonOnSeasonNights() {
        Price price = calculator.calculate(standardRoom,
                stay(LocalDate.of(2027, 2, 25), LocalDate.of(2027, 3, 4), RatePlan.LONG_STAY));
        // 4 nights of 299.88 + 3 nights of 249.90
        assertEquals(new BigDecimal("1949.22"), price.subtotal());
        assertEquals(new BigDecimal("194.92"), price.discount());
    }
}
